function example(arr) {
    // Nested HOFs: arr.map calls arr.filter inside the callback -> O(n^2)
    return arr.map(x => arr.filter(y => y > x));
}

function example(arr, queries) {
    // Category A: arr.includes is O(n) inside an O(n) map -> O(n^2)
    return queries.map(q => arr.includes(q));
}

